import React, { useState, useEffect } from "react";
import { collection, onSnapshot, query, where } from "firebase/firestore";
import { db } from "../../firebase/config"; // Importăm conexiunea la bază
import PetCard from "../../components/PetCard";
import "./AdopterDashboard.css";

const AdopterDashboard = () => {
    const [pets, setPets] = useState([]); // Aici ținem minte animalele reale
    const [loading, setLoading] = useState(true);

    // State-uri pentru filtrare
    const [search, setSearch] = useState("");
    const [filters, setFilters] = useState({
        type: "",
        age: "",
    });

    // 1. CITIREA DATELOR DIN FIREBASE
    useEffect(() => {
        // Creăm o referință către colecția "pets"
        // Putem adăuga `where("adopted", "==", false)` ca să vedem doar animalele disponibile
        const q = query(collection(db, "pets"), where("adopted", "==", false));

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const petsData = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setPets(petsData);
            setLoading(false);
        });

        return () => unsubscribe();
    }, []);

    // 2. LOGICA DE FILTRARE (Rămâne la fel, dar pe datele reale 'pets')
    const filteredPets = pets.filter((pet) => {
        // Căutare text (nume sau rasă)
        const matchSearch =
            pet.name.toLowerCase().includes(search.toLowerCase()) ||
            pet.breed.toLowerCase().includes(search.toLowerCase());

        // Filtru Tip (Câine, Pisică...)
        const matchType = filters.type
            ? pet.type === filters.type // Verificăm exact tipul salvat în DB (ex: "Dog")
            : true;

        // Filtru Vârstă (Simplificat pentru demo)
        // Poți rafina logica asta în funcție de cum salvezi vârsta (număr vs text)
        const matchAge = true;

        return matchSearch && matchType && matchAge;
    });

    return (
        <div className="adopter-container">
            <header className="dashboard-header">
                <div className="header-left">
                    <h1 className="title">🐾 Găsește-ți prietenul ideal</h1>
                    <p className="subtitle">
                        Explorează animalele disponibile pentru adopție de la toate adăposturile.
                    </p>
                </div>
                {/* Aici poți adăuga butonul de profil/logout dacă dorești */}
            </header>

            {/* BARĂ CĂUTARE */}
            <div className="search-section">
                <input
                    type="text"
                    className="search-input"
                    placeholder="Caută după nume, rasă..."
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>

            {/* FILTRE */}
            <div className="filters-container">
                <select
                    className="filter-select"
                    value={filters.type}
                    onChange={(e) => setFilters({ ...filters, type: e.target.value })}
                >
                    <option value="">Toate Tipurile</option>
                    <option value="Dog">Câini</option>
                    <option value="Cat">Pisici</option>
                    <option value="Hamster">Hamsteri</option>
                    <option value="Rabbit">Iepuri</option>
                    <option value="Parrot">Papagali</option>
                </select>

                <select
                    className="filter-select"
                    value={filters.age}
                    onChange={(e) => setFilters({ ...filters, age: e.target.value })}
                >
                    <option value="">Orice Vârstă</option>
                    <option value="puppy">Pui</option>
                    <option value="adult">Adult</option>
                    <option value="senior">Senior</option>
                </select>
            </div>

            {/* LISTA ANIMALE */}
            <h2 className="section-title">Animale Disponibile ({filteredPets.length}) 🐶🐱</h2>

            {loading ? (
                <p>Se încarcă animăluțele...</p>
            ) : filteredPets.length === 0 ? (
                <p>Nu am găsit niciun animal conform criteriilor tale. :(</p>
            ) : (
                <div className="cards-container">
                    {filteredPets.map((pet) => (
                        <PetCard key={pet.id} pet={pet} />
                    ))}
                </div>
            )}
        </div>
    );
};

export default AdopterDashboard;
